13	     * di login. Null = nessuna immagine, viene usato lo sfondo di default.
14	     */
15	    public ?string $login_background_path;
16	
17	    /**
18	     * Colore (esadecimale, es. #000000) dell'overlay applicato sopra
19	     * l'immagine di sfondo della login.
20	     */
21	    public string $login_overlay_color;
22	
23	    /**
24	     * Opacità dell'overlay sopra l'immagine di sfondo della login, da 0
25	     * (trasparente) a 1 (pieno).
26	     */
27	    public float $login_overlay_opacity;
28	
29	    public static function group(): string
30	    {
31	        return 'general';
32	    }
