5	namespace AtrioTeam\DigitalHub\Filament\Pages;
6	
7	use AtrioTeam\DigitalHub\Settings\GeneralSettings;
8	use BackedEnum;
9	use Filament\Forms\Components\ColorPicker;
10	use Filament\Forms\Components\FileUpload;
11	use Filament\Forms\Components\Slider;
12	use Filament\Pages\SettingsPage;
13	use Filament\Schemas\Components\Group;
14	use Filament\Schemas\Components\Section;
15	use Filament\Schemas\Schema;
16	use Filament\Support\Icons\Heroicon;
17	use Illuminate\Support\Facades\Auth;
18	
19	class ManageGeneralSettings extends SettingsPage
20	{
21	    protected static string $settings = GeneralSettings::class;
22	
23	    protected static string|BackedEnum|null $navigationIcon = Heroicon::OutlinedCog6Tooth;
24	
25	    // La pagina è raggiungibile dallo user menu (dropdown del badge utente),
26	    // non dalla sidebar: vedi DigitalHubPlugin::register().
27	    protected static bool $shouldRegisterNavigation = false;
28	
29	    public function getTitle(): string
30	    {
31	        return 'Impostazioni';
32	    }
33	
34	    public static function getNavigationLabel(): string
35	    {
36	        return 'Impostazioni';
37	    }
38	
39	    public function form(Schema $schema): Schema
40	    {
41	        return $schema
42	            ->components([
43	
44	                Section::make('Login')->schema([
45	                    FileUpload::make('login_background_path')
46	                        ->label('Immagine di sfondo')
47	                        ->helperText('Mostrata come sfondo nella schermata di login. Lascia vuoto per usare lo sfondo di default.')
48	                        ->image()
49	                        ->disk('public')
50	                        ->directory('settings')
51	                        ->visibility('public')
52	                        ->imagePreviewHeight('150'),
53	
54	                    Group::make([
55	                        ColorPicker::make('login_overlay_color')
56	                            ->label('Colore overlay')
57	                            ->helperText('Colore steso sopra l\'immagine di sfondo della login.')
58	                            ->required(),
59	                        Slider::make('login_overlay_opacity')
60	                            ->label('Opacità overlay')
61	                            ->hint('0 = overlay trasparente, 1 = colore pieno.')
62	                            ->range(0, 1)
63	                            ->step(0.05)
64	                            ->tooltips()
65	                            ->required(),
66	                    ]),
67	                ])
68	                ->columnSpanFull()
69	                ->columns(2)
70	                ->description('Impostazioni schermata di login')
71	                ->collapsible(),
72	
73	        ]);
74	    }
75	
76	    public static function canAccess(): bool
77	    {
78	        return Auth::user()?->can('manage_settings') ?? false;
79	    }
80	}
