1	<?php
2	
3	declare(strict_types=1);
4	
5	namespace AtrioTeam\DigitalHub\Filament;
6	
7	use AtrioTeam\DigitalHub\Assets\Filament\Pages\AssetManager;
8	use AtrioTeam\DigitalHub\Catalog\Filament\Pages\Catalog;
9	use AtrioTeam\DigitalHub\Filament\Pages\ManageGeneralSettings;
10	use AtrioTeam\DigitalHub\Pim\Filament\Tables\DigitalHubTableMacro;
11	use AtrioTeam\DigitalHub\Settings\GeneralSettings;
12	use Filament\Actions\Action;
13	use Filament\Auth\Pages\Login;
14	use Filament\Auth\Pages\PasswordReset\RequestPasswordReset;
15	use Filament\Auth\Pages\PasswordReset\ResetPassword;
16	use Filament\Contracts\Plugin;
17	use Filament\MinimalTheme;
18	use Filament\Notifications\Livewire\Notifications;
19	use Filament\Panel;
20	use Filament\Support\Enums\Alignment;
21	use Filament\Support\Icons\Heroicon;
22	use Filament\Tables\Table;
23	use Filament\View\PanelsRenderHook;
24	use Illuminate\Support\Facades\Storage;
25	use Illuminate\Support\HtmlString;
26	
27	/**
28	 * A simple Filament plugin to configure the panel via this package.
29	 */
30	class DigitalHubPlugin implements Plugin
31	{
32	    public static function make(): static
33	    {
34	        /** @var static $plugin */
35	        $plugin = app(static::class);
36	
37	        return $plugin;
38	    }
39	
40	    public function getId(): string
41	    {
42	        return 'digital-hub';
43	    }
44	
45	    public function register(Panel $panel): void
46	    {
47	        // Pagine di autenticazione con layout "simple" a cui applicare lo
48	        // sfondo custom: login e recupero password (richiesta link + reset).
49	        $authPages = [
50	            Login::class,
51	            RequestPasswordReset::class,
52	            ResetPassword::class,
53	        ];
54	
55	        $panel
56	            ->plugin(MinimalTheme::make())
57	            ->viteTheme('vendor/atrioteam/digital-hub/resources/theme/digital-hub-theme.css')
58	            ->font('Open Sans')
59	            ->pages([
60	                Catalog::class,
61	                AssetManager::class,
62	                ManageGeneralSettings::class,
63	            ])
64	            // Voce "Impostazioni" nello user menu (dropdown del badge utente),
65	            // non in sidebar (la pagina ha shouldRegisterNavigation = false).
66	            // Visibile solo a chi può gestire le impostazioni.
67	            ->userMenuItems([
68	                Action::make('settings')
69	                    ->label('Impostazioni')
70	                    ->icon(Heroicon::OutlinedCog6Tooth)
71	                    ->url(fn (): string => ManageGeneralSettings::getUrl())
72	                    ->visible(fn (): bool => ManageGeneralSettings::canAccess()),
73	            ])
74	            // Immagine di sfondo nella schermata di login. Il path è gestito dalla
75	            // pagina Impostazioni (GeneralSettings); se non impostato non viene
76	            // iniettato nulla e resta lo sfondo di default. CSS scoped alla login.
77	            ->renderHook(
78	                PanelsRenderHook::HEAD_END,
79	                function (): string|HtmlString {
80	                    $settings = app(GeneralSettings::class);
81	
82	                    if (blank($settings->login_background_path)) {
83	                        return '';
84	                    }
85	
86	                    $url = Storage::disk('public')->url($settings->login_background_path);
87	                    $overlay = self::overlayRgba($settings->login_overlay_color, $settings->login_overlay_opacity);
88	
89	                    return new HtmlString(
90	                        '<style>
91	                            .fi-simple-layout {
92	                                background-image: linear-gradient(' . $overlay . ', ' . $overlay . '), url("' . e($url) . '");
93	                                background-size: cover;
94	                                background-position: center;
95	                                background-repeat: no-repeat;
96	                            }
97	                        </style>',
98	                    );
99	                },
100	                scopes: $authPages,
101	            )
102	            ->renderHook(
103	                PanelsRenderHook::SIMPLE_PAGE_START,
104	                fn () => '<div class="afh-login-wrapper">',
105	                scopes: $authPages,
106	            )
107	            ->renderHook(
108	                PanelsRenderHook::SIMPLE_PAGE_END,
109	                fn () => '</div>',
110	                scopes: $authPages,
111	
112	            )
113	            
114	            
115	            ;
116	
117	        $primaryColor = config('digital-hub.primary_color');
118	        if (is_string($primaryColor) && $primaryColor !== '') {
119	            /** @var array<int, string> $color */
120	            $color = \Filament\Support\Colors\Color::{$primaryColor};
121	            $panel
122	            ->colors([
123	                'primary' => $color,
124	            ]);
125	        }
126	
127	    }
128	
129	    public function boot(Panel $panel): void
130	    {
131	        Notifications::alignment(Alignment::Center);
132	
133	        Table::configureUsing(function (Table $table): Table {
134	            return $table->defaultPaginationPageOption(50);
135	        });
136	
137	        DigitalHubTableMacro::register();
138	
139	
140	    }
141	
142	    /**
143	     * Costruisce una stringa CSS `rgba(...)` per l'overlay della login a partire
144	     * dal colore esadecimale (#rgb o #rrggbb) e dall'opacità (0..1) salvati nelle
145	     * impostazioni. Input non validi degradano a nero/opacità clampata.
146	     */
147	    private static function overlayRgba(string $hex, float $opacity): string
148	    {
149	        $hex = ltrim($hex, '#');
150	
151	        if (strlen($hex) === 3) {
152	            $hex = $hex[0] . $hex[0] . $hex[1] . $hex[1] . $hex[2] . $hex[2];
153	        }
154	
155	        if (! ctype_xdigit($hex) || strlen($hex) !== 6) {
156	            $hex = '000000';
157	        }
158	
159	        $r = (int) hexdec(substr($hex, 0, 2));
160	        $g = (int) hexdec(substr($hex, 2, 2));
161	        $b = (int) hexdec(substr($hex, 4, 2));
162	        $alpha = max(0.0, min(1.0, $opacity));
163	
164	        return sprintf('rgba(%d, %d, %d, %s)', $r, $g, $b, rtrim(rtrim(number_format($alpha, 2, '.', ''), '0'), '.'));
165	    }
166	
167	}
