 * durante le migration) si ricade sul config senza sollevare eccezioni.
 */
private static function resolvePrimaryColor(): ?string
{
    try {
        $fromSettings = app(GeneralSettings::class)->primary_color;

        if (is_string($fromSettings) && $fromSettings !== '') {
            return $fromSettings;
        }
    } catch (\Throwable) {
