/**
 * Risolve la palette colori (shade 50..950) da usare come primary del panel.
 * Ordine: setting general.primary_color (modalità "palette" = nome costante
 * Filament, "custom" = hex libero da cui generare la palette), poi fallback
 * sul config. Se la lettura delle settings fallisce (DB/tabella non
 * disponibile in console o durante le migration) si ricade sul config senza
 * sollevare eccezioni. Ritorna null se non c'è alcun colore configurato.
 *
 * @return array<int, string>|null
 */
private static function resolvePrimaryPalette(): ?array
{
    try {
        $settings = app(GeneralSettings::class);

        if ($settings->primary_color_mode === 'custom') {
            if (filled($settings->primary_color_custom)) {
                return \Filament\Support\Colors\Color::hex($settings->primary_color_custom);
            }
        } elseif (filled($settings->primary_color)) {
            return self::paletteFromName($settings->primary_color);
        }
    } catch (\Throwable) {
        // settings non disponibili: si usa il config
    }

    $fromConfig = config('digital-hub.primary_color');

    return is_string($fromConfig) && $fromConfig !== ''
        ? self::paletteFromName($fromConfig)
        : null;
}

/**
 * Restituisce la palette di una costante colore di Filament dato il suo nome
 * (es. "Amber"), o null se il nome non corrisponde ad alcuna costante.
 *
 * @return array<int, string>|null
 */
private static function paletteFromName(string $name): ?array
{
    if (! defined(\Filament\Support\Colors\Color::class . '::' . $name)) {
        return null;
    }

    /** @var array<int, string> $palette */
    $palette = \Filament\Support\Colors\Color::{$name};

    return $palette;
}

