/**
 * Genera il blocco <style> che sovrascrive il colore dei button primari
 * (pieni). Agisce solo su `.fi-color-primary` non-outlined, impostando le
 * variabili CSS di Filament (--bg/--text e relativi stati hover/dark) con
 * `!important` per battere gli stili inline del componente. Il testo è
 * calcolato per contrasto; l'hover scurisce leggermente lo sfondo.
 */
private static function buttonColorStyle(string $hex): string
{
    $bg = e($hex);
    $text = e(self::contrastingTextColor($hex));
    $hover = 'color-mix(in oklab, ' . $bg . ' 90%, black)';

    return '<style>
        .fi-btn.fi-color-primary:not(.fi-outlined):not(label) {
            --bg: ' . $bg . ' !important;
            --hover-bg: ' . $hover . ' !important;
            --text: ' . $text . ' !important;
            --hover-text: ' . $text . ' !important;
            --dark-bg: ' . $bg . ' !important;
            --dark-hover-bg: ' . $hover . ' !important;
            --dark-text: ' . $text . ' !important;
            --dark-hover-text: ' . $text . ' !important;
        }
    </style>';
}

/**
 * Sceglie tra testo chiaro (#ffffff) e scuro (#111827) quello con il
 * contrasto migliore rispetto al colore di sfondo dato, così il testo dei
 * button resta leggibile qualunque colore venga scelto.
 */
private static function contrastingTextColor(string $background): string
{
    $light = '#ffffff';
    $dark = '#111827';

    try {
        $againstLight = \Filament\Support\Colors\Color::calculateContrastRatio($background, $light);
        $againstDark = \Filament\Support\Colors\Color::calculateContrastRatio($background, $dark);

        return $againstDark >= $againstLight ? $dark : $light;
    } catch (\Throwable) {
        return $dark;
    }
}

