class GeneralSettings extends Settings
{
    /**
     * Path (relativo al disco public) dell'immagine di sfondo della schermata
     * di login. Null = nessuna immagine, viene usato lo sfondo di default.
     */
    public ?string $login_background_path;

    /**
     * Colore (esadecimale, es. #000000) dell'overlay applicato sopra
     * l'immagine di sfondo della login.
     */
    public string $login_overlay_color;

    /**
     * Opacità dell'overlay sopra l'immagine di sfondo della login, da 0
     * (trasparente) a 1 (pieno).
     */
    public float $login_overlay_opacity;

    /**
     * Path (relativo al disco public) del logo del panel mostrato nella
     * topbar/brand. Null = nessun logo custom, viene usato il default di Filament.
     */
    public ?string $panel_logo_path;

    /**
     * Altezza del logo del panel come valore CSS (es. "2rem", "40px").
     * Null = altezza di default di Filament.
     */
    public ?string $panel_logo_height;

    /**
     * Modalità di scelta del primary color: "palette" usa un colore predefinito
     * di Filament (vedi $primary_color), "custom" usa un hex libero (vedi
     * $primary_color_custom). Null = comportamento di default (config).
     */
    public ?string $primary_color_mode;

    /**
     * Nome di una costante colore di \Filament\Support\Colors\Color (es. "Amber",
     * "Blue") usata come primary color del panel. Il primary determina, tra le
     * altre cose, il colore della voce attiva nella sidebar. Null = si usa il
     * valore del config digital-hub.primary_color. Usato quando mode = "palette".
     */
    public ?string $primary_color;

    /**
     * Colore primario personalizzato in formato hex (es. "#3b82f6"). Da questo
     * Filament genera l'intera palette (shade 50..950). Usato quando
     * mode = "custom".
     */
    public ?string $primary_color_custom;

    /**
     * Colore del testo (e icona) dei button primari (pieni) in formato hex.
     * Default "#ffffff" (bianco). Lo sfondo dei button resta invariato. Null =
     * nessun override, si usa il colore di default di Filament.
     */
    public ?string $button_text_color;

    public static function group(): string
    {
        return 'general';
    }
}
