    private static function paletteFromName(string $name): ?array
    {
        if (! defined(\Filament\Support\Colors\Color::class . '::' . $name)) {
            return null;
        }

        /** @var array<int, string> $palette */
        $palette = \Filament\Support\Colors\Color::{$name};

        return $palette;
    }

    /**
     * Genera il blocco <style> che sovrascrive il colore del testo (e icona) dei
     * button primari (pieni). Agisce solo su `.fi-color-primary` non-outlined,
     * impostando le variabili CSS del testo di Filament (--text e relativi stati
     * hover/dark) con `!important` per battere gli stili inline del componente.
     * Lo sfondo dei button resta invariato.
     */
    private static function buttonTextColorStyle(string $hex): string
    {
        $text = e($hex);

        return '<style>
            .fi-btn.fi-color-primary:not(.fi-outlined):not(label) {
                --text: ' . $text . ' !important;
                --hover-text: ' . $text . ' !important;
                --dark-text: ' . $text . ' !important;
                --dark-hover-text: ' . $text . ' !important;
            }
        </style>';
    }

    /**
     * Costruisce una stringa CSS `rgba(...)` per l'overlay della login a partire
     * dal colore esadecimale (#rgb o #rrggbb) e dall'opacità (0..1) salvati nelle
     * impostazioni. Input non validi degradano a nero/opacità clampata.
     */
    private static function overlayRgba(string $hex, float $opacity): string
    {
        $hex = ltrim($hex, '#');

        if (strlen($hex) === 3) {
            $hex = $hex[0] . $hex[0] . $hex[1] . $hex[1] . $hex[2] . $hex[2];
        }

        if (! ctype_xdigit($hex) || strlen($hex) !== 6) {
            $hex = '000000';
        }

        $r = (int) hexdec(substr($hex, 0, 2));
        $g = (int) hexdec(substr($hex, 2, 2));
        $b = (int) hexdec(substr($hex, 4, 2));
        $alpha = max(0.0, min(1.0, $opacity));

        return sprintf('rgba(%d, %d, %d, %s)', $r, $g, $b, rtrim(rtrim(number_format($alpha, 2, '.', ''), '0'), '.'));
    }

}

